-- Seed: walking-tour places from data/places.jsonl -> public.waypoints
--
-- The source file holds 456 records scraped from published self-guided walking
-- tours across 35 cities. 406 rows survive here; the other 50 are exact
-- name + city duplicates within the file (Jacksonville's churches appear up to
-- four times, New Orleans' French Quarter block twice), collapsed by keeping the
-- richest copy of each — coordinates first, then a source URL, then a street
-- address, then the longer description.
--
-- Column mapping:
--   name         <- name
--   city / state <- city. "New Orleans, LA" splits to New Orleans + LA. The
--                   Madrid rows carry no state, so the country is lifted off the
--                   end of the address instead: state = 'Spain', which is the
--                   site's convention for non-US places.
--   zip          <- postal code lifted off the end of address (US ZIP, Canadian
--                   postal code, or the Spanish code that precedes the city)
--   address      <- the street line only, with the trailing ", City, ST ZIP"
--                   removed, the way the rest of the table stores it
--   description  <- description
--   source_url   <- source.url
--
-- Not carried over, because there are no columns for them: category, on_tours,
-- start_candidate / end_candidate, w3w — the what3words column was dropped on
-- 2026-07-27 when the account was cancelled (2026072703_drop_waypoint_w3w) —
-- and lat / lng.
--
-- ON COORDINATES: 24 of these rows carry lat/lng and the data is thrown away
-- here, because public.waypoints has no lat/lon columns. They were added by
-- 20260620_add_waypoints_latlon.sql and dropped later straight in the dashboard;
-- the repo never got a migration for the drop, so 20260620 still reads as though
-- they exist and only an aside in 2026072703 records that they don't. If those
-- coordinates are worth keeping, the columns have to come back first — the
-- source values are in the git history of data/places.jsonl.
--
-- wpid is assigned by the table's trigger. Idempotent: the not-exists guard
-- matches on name + city, so a re-run inserts nothing, rows already seeded by
-- 20260626_atlanta_phoenix_waypoints are skipped rather than duplicated, and a
-- row since archived as a do-not-rescrape tombstone is NOT resurrected.
--
-- NOTE ON CITIES: waypoints.city has no FK to public.cities, but the waypoints
-- page joins the two by city name and 2026072702 once deleted waypoints whose
-- city was not in the catalog. Madrid, San Jose, Ottawa and Winnipeg may not be
-- in `cities`; check before running if you care about those showing up in the
-- city filter:
--   select distinct w.city from public.waypoints w
--    where not exists (select 1 from public.cities c
--                       where lower(split_part(c.city, ',', 1)) = lower(w.city));

insert into public.waypoints (name, city, state, zip, address, description, source_url)
select v.name, v.city, v.state, v.zip, v.address, v.description, v.source_url
from (values
  ('APEX Museum', 'Atlanta', 'GA', '30303', '135 Auburn Ave NE SE', 'Atlanta''s oldest Black history museum, chronicling the African diaspora and the cultural achievements of the Sweet Auburn neighborhood.', 'https://discoveratlanta.com/explore/itineraries/auburn-avenue-black-history/'),
  ('Big Bethel AME Church', 'Atlanta', 'GA', '30303', '220 Auburn Ave NE', 'The oldest African American church on Auburn Avenue, founded in 1840, featuring a prominent ''Jesus Saves'' neon sign on its steeple.', 'https://rogersredjackettours.com/sweet-auburn-walking-tour/'),
